async () => {
  // Try to find a task that matches the description of sending documents to the dean's office
  let found = await api.findTasks({query: 'документы в деканат'});
  if (found.length === 1) {
    return {actions: [{type: 'complete', task_ref: found[0].ref}]};
  }
  // fallback to a broader query
  found = await api.findTasks({query: 'деканат'});
  if (found.length === 1) {
    return {actions: [{type: 'complete', task_ref: found[0].ref}]};
  }
  if (found.length > 1) {
    // ambiguous which task to complete
    return {clarification: 'У вас несколько задач, связанных с деканатом. Уточните, какую из них нужно отметить выполненной.'};
  }
  // no matching task found
  return {decline: {reason: 'unclear', answer: 'Не нашёл задачу, связанную с отправкой документов в деканат. Пожалуйста, уточните название задачи.'}};
}

async () => {
  const selector = { group: 'Учёба', overdue: true, all: true };
  const found = await api.findTasks(selector);
  const newDeadline = '2030-11-15T18:00:00+03:00';
  const actions = found.map(t => ({
    type: 'reschedule',
    task_ref: t.ref,
    new_deadline: newDeadline
  }));
  return { actions };
}
